from dataclasses import dataclass


@dataclass
class Complex:
    re: float
    im: float


def add(x, y):
    return Complex(x.re + y.re, x.im + y.im)


def mul(x, y):
    return Complex(x.re * y.re - x.im * y.im, x.re * y.im + x.im * y.re)


def main():
    a_re, a_im = map(float, input().split())
    b_re, b_im = map(float, input().split())
    a = Complex(a_re, a_im)
    b = Complex(b_re, b_im)

    s = add(a, b)
    p = mul(a, b)

    print(f"{s.re:.2f} {s.im:.2f}")
    print(f"{p.re:.2f} {p.im:.2f}")


