@dataclass
class Date:
    year: int
    month: int
    day: int


DAYS = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]


def is_leap(year):
    return (year % 4 == 0 and year % 100 != 0) or year % 400 == 0


def day_of_year(d):
    total = d.day
    for i in range(d.month - 1):
        total += DAYS[i]
    if d.month > 2 and is_leap(d.year):
