import sys


def is_prime(n):
    if n < 2:
        return False
    i = 2
    while i * i <= n:
        if n % i == 0:
            return False
        i += 1
    return True


def main():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    numbers = [int(t) for t in data[1:1 + n]]
    cnt = 0
    total = 0
    for x in numbers:
        if is_prime(x):
            cnt += 1
            total += x
    print(cnt, total)


main()

